styles.h1:
font-size: 22px;
line-height: 1.4;
font-weight: 600;
color: #1c1f23;
position: relative;
text-align: center;
padding: 0 0 14px 0;

styles.h2:
display: table;
padding: 0.4em 1.4em;
margin: 3em auto 1.5em;
color: #fff;
background: linear-gradient(135deg, #1677ff, #05d4cd);
font-size: 1.3em;
font-weight: 600;
text-align: center;
border-radius: 8px 24px 8px 24px;
box-shadow: 0 4px 12px rgba(5, 212, 205, 0.15);
position: relative;
letter-spacing: 0.02em;

styles.h3:
padding: 0.5em 1em 0.5em 12px;
font-size: 1.2em;
border-radius: 6px;
line-height: 1.6;
border-left: 4px solid #1677ff;
border-right: 1px solid rgba(22, 119, 255, 0.1);
border-bottom: 1px solid rgba(22, 119, 255, 0.1);
border-top: 1px solid rgba(22, 119, 255, 0.1);
background: rgba(22, 119, 255, 0.05);
color: #1677ff;
margin: 2em 0 0.75em;
font-weight: 600;
position: relative;

styles.h6:
color: #6b8c42;
margin-top: 1.2em;
margin-bottom: 0.5em;
font-weight: 700;
border-bottom: 1px solid #d4d9c9;
padding-bottom: 0.3em;

styles.a:
font-family:
  "Helvetica Neue", Helvetica, Arial, "PingFang SC", "Hiragino Sans GB",
  "Microsoft YaHei", sans-serif;
box-shadow: 0 8px 24px rgba(255, 106, 0, 0.1);
background: #ffffff;
position: relative;

styles.blockquote:
background: rgba(0, 102, 255, 0.04);
border-left: 4px solid #0066ff;
border-radius: 0 8px 8px 0;
position: relative;

styles.code:
font-family: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
background: rgba(0, 0, 0, 0.04);
padding: 2px 6px;
border-radius: 4px;
font-size: 14px;
color: #fa2c19;
border-bottom: 2px solid rgba(250, 44, 25, 0.1);

styles.pre:
background: #f7f8fa;
border-radius: 6px 12px 6px 12px;
padding: 16px;
overflow-x: auto;
position: relative;
border: 1px solid #ebedf0;

styles.hr:
border: 0;
height: 1px;
background: linear-gradient(90deg, transparent, #d4af37, transparent);
margin: 30px 0;
position: relative;

styles.img:
max-width: 100%;
border: 1px solid #d4af37;
padding: 5px;
background-color: #0a0a0a;
position: relative;

styles.table:
width: 100%;
border-collapse: separate;
border-spacing: 0;
font-size: 14px;
border-radius: 8px;
box-shadow: 0 0 0 1px rgba(0, 102, 255, 0.1);

styles.th:
background: rgba(0, 102, 255, 0.06);
font-weight: 600;
text-align: left;
padding: 10px 12px;
color: #1c1f23;
border-bottom: 2px solid rgba(0, 102, 255, 0.1);

